double h = (b - a) / 2.0;
double fa = f(a);
double fb = f(b);
double fc = f((a + b) / 2.0);
double integral = (h / 2.0) * (fa + fb);
double error = std::abs((h / 6.0) * (fa + 4.0 * fc + fb) - integral);

while (error > precision) {
    h /= 2.0;
    double sum = 0.0;
    int n = std::ceil((b - a) / h);
    for (int i = 1; i < n; i++) {
        sum += f(a + i * h);
    }
    integral = (h / 2.0) * (f(a) + f(b) + 2.0 * sum);
    error = std::abs((h / 6.0) * (f(a) + 4.0 * sum + f(b)) - integral);
}

return integral;

